#!/bin/sh
services_menu(){ while :; do c=$(ui_menu Services "Init: $INIT_SYSTEM" status 'Inspect common services' manage 'Manage a named service' enabled 'List enabled services' startup 'Configure rc.local/startup script' cron 'Configure cron' logs 'Inspect logs' autostart 'Create login autostart command') || { _menu_rc=$?; [ "$_menu_rc" -eq "${UI_MENU_BACK_RC:-90}" ] && return 0; return "$_menu_rc"; }; case $c in status) for s in sshd ssh cron crond rsyslog syslog-ng chronyd ntpd; do printf '%-12s %s\n' "$s" "$(service_state "$s")"; done >"$TMP_DIR/services"; ui_text Services "$(cat "$TMP_DIR/services")";; manage) service_manage;; enabled) case $INIT_SYSTEM in openrc) rc-update show;; systemd) systemctl list-unit-files --state=enabled;; runit) ls -l /var/service;; sysv) find /etc/rc*.d -type l;; esac >"$TMP_DIR/enabled" 2>&1; ui_text Enabled "$(cat "$TMP_DIR/enabled")";; startup) [ -e /etc/rc.local ] || write_file /etc/rc.local 755 '#!/bin/sh\nexit 0'; edit_file /etc/rc.local;; cron) cron_menu;; logs) ui_text Logs "$(tail -n 150 /var/log/messages /var/log/syslog /var/log/auth.log 2>/dev/null)";; autostart) cmd=$(ui_input Autostart 'Command:' '') || continue; replace_block "$CURRENT_HOME/.profile" autostart "$cmd >/dev/null 2>&1 &";; esac; done; }
service_manage(){ s=$(ui_input Service 'Service name:' sshd) || return; a=$(ui_menu "$s" "Current: $(service_state "$s")" start Start stop Stop restart Restart enable Enable disable Disable status Status) || { _menu_rc=$?; [ "$_menu_rc" -eq "${UI_MENU_BACK_RC:-90}" ] && return 0; return "$_menu_rc"; }; case $a in start) run_capture Service service_start "$s";; stop) run_capture Service service_stop "$s";; restart) run_capture Service service_restart "$s";; enable) run_capture Service service_enable "$s";; disable) run_capture Service service_disable "$s";; status) ui_msg Service "$(service_state "$s")";; esac; }
cron_menu(){ c=$(ui_menu Cron 'Cron configuration.' user 'Edit user crontab' root 'Edit root crontab' periodic 'List periodic jobs' install 'Install cron daemon') || { _menu_rc=$?; [ "$_menu_rc" -eq "${UI_MENU_BACK_RC:-90}" ] && return 0; return "$_menu_rc"; }; case $c in user) crontab -e;; root) as_root crontab -e;; periodic) ui_text Periodic "$(find /etc/periodic /etc/cron.* -maxdepth 2 -type f 2>/dev/null)";; install) case $PKG_MGR in apk) run_capture Cron pkg_install dcron;; apt) run_capture Cron pkg_install cron;; *) run_capture Cron pkg_install cronie;; esac;; esac; }
